from lib import *
S = SS('g57')
steps = [
    step("8 个 goroutine 争同一把 sync.Mutex,每次在锁里睡 1 ms,各 20 次(共 160 次、至少 160 ms 的串行时间),SetBlockProfileRate(1) 与 SetMutexProfileFraction(1)。整个程序用时 0.201 秒。block profile(delay)总计 1564.82ms:sync.(*Mutex).Lock 1363.67ms(87.15%),sync.(*WaitGroup).Wait 201.15ms(12.85%)。mutex profile 总计 1363.74ms,全部记在 sync.(*Mutex).Unlock 上。", t=tl(S(1)), done=lidx(S(1), 'TOTAL 0.201', 'sync.(*Mutex).Lock (inline)', 'sync.(*WaitGroup).Wait'), mark=lidx(S(1), 'sync.(*Mutex).Unlock (inline)', '-- mutex profile'), b=bars([['block:Lock 上的等待 (ms)', 1363.67, '1363.67'], ['block:WaitGroup.Wait', 201.15, '201.15'], ['mutex:Unlock 上记的延迟', 1363.74, '1363.74']], 1363.74, done=[0, 1], mark=[2]), kv=KV([['block profile', '记在等待者:Lock 1363.67 ms,Wait 201.15 ms'], ['mutex profile', '记在持锁者释放处:Unlock 1363.74 ms'], ['两者的同一件事', '锁竞争的总延迟几乎相同']], ['两者的同一件事'])),
    step("block profile 也记录 channel 等待,mutex profile 不记录:main 在 <-ch 上等 300 ms。block profile:1 次事件,累计延迟 302 ms;mutex profile:0 次事件,累计延迟 0 ms。", t=tl(S(2)), done=lidx(S(2), 'block profile:1 次事件'), mark=lidx(S(2), 'mutex profile:0 次事件'), kv=KV([['block profile', '1 次事件,302 ms'], ['mutex profile', '0 次事件']], ['mutex profile'])),
    step("采样设置影响读数(同一个竞争程序,各 5 次)。block rate=1 / mutex fraction=1:block 延迟 1568–1571 ms(事件 160 次),mutex 延迟 1367–1369 ms(事件 159 次)。block rate=1000000 / fraction=10:block 1569–1571 ms(事件 160 次),mutex 957–1595 ms(事件 120–190 次)。block rate=100000000 / fraction=100:block 1002–2001 ms(事件 91–208 次),mutex 0–1761 ms(事件 0–200 次)。", t=tl(S(3)), done=lidx(S(3), 'block rate=        1,'), mark=lidx(S(3), 'mutex fraction= 10:', 'mutex fraction=100:'), b=bars([['rate=1:mutex 波动(ms)', 2, '2'], ['fraction=10:mutex 波动', 638, '638'], ['fraction=100:mutex 波动', 1761, '1761']], 1761, done=[0], mark=[1, 2]), kv=KV([['全采样', '读数稳定(160 / 159 次)'], ['fraction=10', 'mutex 事件 120–190 次'], ['fraction=100', 'mutex 事件 0–200 次,可能读到 0']], ['fraction=100'])),
    step("打开 profile 的代价(速率 0 对 1):无竞争的 Lock+Unlock 都是 7 ns/次;8 个 goroutine 争同一把锁各 200000 次,速率 0 平均每次 125 ns,速率 1 平均每次 105 ns——这次测量里打开 profile 没有变慢(两个数字的差在噪声里,我没有重复)。", t=tl(S(4)), mark=lidx(S(4), '速率 1('), done=lidx(S(4), '速率 0('), b=bars([['速率 0 无竞争 (ns)', 7, '7'], ['速率 1 无竞争', 7, '7'], ['速率 0 争锁', 125, '125'], ['速率 1 争锁', 105, '105']], 125, done=[0, 2], mark=[1, 3]), kv=KV([['无竞争', '7 ns 对 7 ns'], ['争锁', '125 ns 对 105 ns(差在噪声里)'], ['限制', '只测了一次']], ['限制'])),
    step("文档原文:SetBlockProfileRate——目标是平均每 rate 纳秒的阻塞时间采样一个阻塞事件,传 1 记录每个事件,传 ≤ 0 关闭;SetMutexProfileFraction——平均每 rate 个事件报告 1 个,返回之前的值,传 0 关闭,传 < 0 只读取当前值,并注明 n>1 时采样细节可能改变。", t=tl(S(5)), done=lidx(S(5), 'one blocking event per rate nanoseconds', 'pass rate = 1'), mark=lidx(S(5), 'On average 1/rate events', 'pass rate < 0', 'details of sampling may change'), kv=KV([['block rate', '按阻塞的纳秒数采样;1 = 全部;≤0 = 关'], ['mutex fraction', '平均 1/rate 的事件;0 = 关;<0 = 只读'], ['注意', 'n>1 时采样细节可能改变']], ['注意'])),
]
